import collections,csv,glob,os,subprocess
root=os.getcwd(); rows=list(csv.DictReader(open('souji-shokunin/census/round-3/operator-approval-list.tsv'),delimiter='\t')); paths=[r['path'] for r in rows]
missing=[]; no_intro=[]; nonancestor=[]
for p in paths:
 rel=os.path.relpath(p,root)
 if not os.path.exists(p): missing.append(p)
 intro=subprocess.run(['git','-C',root,'log','--diff-filter=A','--format=%H','-1','--',rel],capture_output=True,text=True).stdout.strip().splitlines()
 if not intro: no_intro.append(p)
 elif subprocess.run(['git','-C',root,'merge-base','--is-ancestor',intro[0],'refs/remotes/origin/master']).returncode: nonancestor.append(p)
shards=[r for f in glob.glob('souji-shokunin/census/round-3/approvals-*.tsv') for r in csv.DictReader(open(f),delimiter='\t')]
print('approval_rows=%d unique_paths=%d missing=%d intro_missing=%d nonancestor_origin_master=%d shard_rows=%d shard_verdicts=%s' % (len(rows),len(set(paths)),len(missing),len(no_intro),len(nonancestor),len(shards),dict(collections.Counter(r['verdict'] for r in shards))))
print('literal_ancestor_yes=%d alternate_intro_ancestor_origin_master=%d' % (sum('ancestor=yes' in r['evidence'] for r in rows),sum('intro ancestor of origin/master' in r['evidence'] for r in rows)))
for repo in ('lore-shokunin','game-dev-2d-shokunin'):
 out=subprocess.check_output(['git','-C',os.path.join(root,repo),'worktree','list','--porcelain'],text=True)
 print('%s_worktree_entries=%d' % (repo,sum(x.startswith('worktree ') for x in out.splitlines())))
for b in ('wt-r98','wt-r99','wt-r100'):
 out=subprocess.check_output(['git','-C',os.path.join(root,'game-dev-2d-shokunin'),'log','--oneline',b,'--not','--remotes'],text=True)
 print('%s_unpushed_commits=%d' % (b,sum(bool(x) for x in out.splitlines())))
